SELECT L.DesignId, L.LayoutCode, L.LayoutName, L.LayoutDesc, L.ParentLayoutCode, L.LayoutLevel, L.LayoutSeq, L.ImgName, L.ImgLink, L.ImgWidth, L.ImgHeight, L.State, L.Remark, L.RegistDate, L.RegistId, L.RegistName, L.ChangeDate, L.ChangeId, L.ChangeName, (SELECT COUNT(*) FROM shopion.tStrLayout C WHERE C.DesignId = L.DesignId AND C.ParentLayoutCode = L.LayoutCode) AS ChildCount FROM shopion.tStrLayout L
AND L.DesignId = #{pDesignId}
AND L.ParentLayoutCode = #{pParentLayoutCode}
AND L.LayoutLevel = 0
AND L.LayoutCode IN
#{item}
ORDER BY L.LayoutSeq

SELECT MAX(LayoutCode)
FROM shopion.tStrLayout


        AND DesignId = #{pDesignId}


        AND ParentLayoutCode = #{pParentLayoutCode}

SELECT DesignId, LayoutCode, LayoutName, LayoutDesc, ParentLayoutCode,
       LayoutLevel, LayoutSeq, ImgName, ImgLink, ImgWidth, ImgHeight, ImgHtml,
       State, Remark, RegistDate, RegistId, RegistName, ChangeDate, ChangeId, ChangeName
FROM shopion.tStrLayout
WHERE DesignId = #{pDesignId}
  AND LayoutCode = #{pLayoutCode}

SELECT ImgHtml
FROM shopion.tStrLayout
WHERE DesignId = #{pDesignId}
  AND LayoutCode = #{pLayoutCode}

