mapper.update:
UPDATE shopion.tStrLayout SET LayoutName = #{layoutName}, LayoutDesc = #{layoutDesc}, ParentLayoutCode = #{parentLayoutCode}, LayoutLevel = #{layoutLevel}, LayoutSeq = #{layoutSeq}, ImgName = #{imgName}, ImgLink = #{imgLink}, ImgWidth = #{imgWidth}, ImgHeight = #{imgHeight},
ImgHtml = #{imgHtml},
State = #{state}, Remark = #{remark}, ChangeDate = #{changeDate}, ChangeId = #{changeId}, ChangeName = #{changeName} WHERE DesignId = #{designId} AND LayoutCode = #{layoutCode}

